// One table, three questions. Pure: no clock of its own, no I/O, no DOM.
//
// The repo page used to carry two tables — every declared task in one, every open work
// item in the other — and they were the same rows twice. A task's row could not say
// what its item was doing without repeating the item table, and an item's row could not
// say what it was FOR without repeating the roster. Worse, the reader had to join them
// by eye to answer the only question they open this page with: is anything stuck.
//
// So there is one row per piece of work, and the view decides which rows and which
// columns:
//
//   STUCK   — something has stopped. A park, a blown leash, an item off the state
//             machine, a task whose lane is held. This is the list to act on.
//   PENDING — work in flight or queued: an item exists and is moving.
//   ALL     — every declared task, including the ones that have never run, which is
//             the case a list built from items alone would silently omit.
//
// The classification is one function so the three views cannot disagree about what
// "stuck" means, and the ordering is severity-first so the top of any view is the worst
// thing true of this repo.

import {
  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_ACTION,
} from '../../engine/scheduler/queue/work-item.mjs';

export const VIEWS = Object.freeze(['stuck', 'pending', 'all']);

// The severity ladder, worst first — the same words and the same order the fleet page
// ranks members by, so a reader moving between the two pages is reading one scale.
const LEVELS = ['critical', 'serious', 'warning', 'info', 'ok'];
const levelRank = (l) => {
  const i = LEVELS.indexOf(l);
  return i === -1 ? LEVELS.length : i;
};

// The machine states an item can be in and still be moving. Anything else an OPEN item
// wears — a park, a torn label swap, no label at all — is a stop.
const MOVING = new Set([BLOCKED, READY, EXECUTING, AGENT]);

// What is wrong with this row, worst first, or an empty list. Every entry mirrors
// something the engine will actually act on (or has stopped acting on), never a display
// heuristic — the warnings come from `describeItem`, which reads the real recovery
// rules, and the two added here are the two the item cannot state about itself.
export function troubles(row) {
  const out = [];
  const item = row.current;
  if (item) {
    if (item.state === NEEDS_HUMAN) {
      out.push({
        level: item.blockingPark ? 'critical' : (item.triage === NEEDS_HUMAN_APPROVAL ? 'warning' : 'serious'),
        text: item.warnings.find((w) => w.text.startsWith('parked'))?.text ?? 'parked for a human',
      });
    }
    for (const w of item.warnings) {
      if (w.text.startsWith('parked')) continue;      // already said, at its own severity
      out.push(w);
    }
    if (!MOVING.has(item.state) && item.state !== NEEDS_HUMAN) {
      out.push({ level: 'warning', text: 'off the state machine — the janitor repairs it' });
    }
====
  [NEEDS_HUMAN_APPROVAL]: 'a PR to approve',
  [NEEDS_HUMAN_ACTION]: 'something to change outside the code',
  [NEEDS_HUMAN_DECISION]: 'a decision to make',
  [NEEDS_HUMAN_FAILURE]: 'a break to diagnose, holding the task\'s lane',
};

// The outcome as its canonical word ('done' | 'delivered' | 'obsolete' | null) —
// the engine's decoder, which maps every legacy spelling straight to today's.
export const outcomeOf = decodeOutcome;

// How long the item has sat where it is. Every transition is a label write, so
// `updated_at` is the last touch — the same quantity the janitor's rules count.
const idleMs = (item, now) => ms(now) - (ms(item?.updated_at) ?? ms(item?.created_at) ?? ms(now));

// Warnings, each mirroring a real recovery rule rather than a display heuristic, so
// what the page flags is what the engine will actually act on — and how long the
// viewer waits for it.
//
// `isOpen(number)` answers whether a `Blocked-by` issue is still open — true, false,
// or null for one outside what the caller fetched. Unknown is never alarmed on.
export function warningsFor(item, now, { periodFor = () => null, isOpen = () => null } = {}) {
  const out = [];
  const state = stateOf(item);
  const idle = idleMs(item, now);
  if (state === EXECUTING && idle >= EXECUTING_LEASH_MS) {
    out.push({ level: 'serious', text: 'executing past the leash — the next scheduler run reclaims it' });
  }
  if (state === AGENT && idle >= AGENT_LEASH_MS) {
    out.push({ level: 'serious', text: 'agent claim past the leash — the janitor reclaims it' });
  }
  if (state === READY) {
    const per = periodFor(`${parseWorkItemTitle(item.title)?.pack}/${parseWorkItemTitle(item.title)?.task}`) ?? 86400e3;
    if (idle >= STALE_READY_PERIODS * per) out.push({ level: 'serious', text: 'ready but unpicked for ~2 periods' });
  }
  if (state === BLOCKED) {
    // The standing-item model: blocked is the queue's healthy quiet state, not a
    // fault. A rolled item waiting out its Not-before never warns; what does warn is
    // the two things the engine would actually act on — dependencies unresolved past
    // the janitor's threshold, and an item DUE that the scheduler run has failed to ready.
    const { notBefore, blockedBy } = parseWorkItemBody(item.body);
    const wake = ms(notBefore);
    const depStates = blockedBy.map((n) => isOpen(n));
    if (wake !== null && wake > ms(now)) {
      // waiting out its stamped wake — healthy, whatever its age
    } else if (depStates.some((s) => s === true)) {
      if (idle >= STUCK_BLOCKED_MS) {
        out.push({ level: 'warning', text: `blocked on ${blockedBy.map((n) => `#${n}`).join(', ')} for over 2 days — the janitor flags stuck dependencies` });
      }
    } else if (!depStates.some((s) => s === null)) {
      // Nothing blocks it any more: the next scheduler run readies it. Due only measures from
      // the stamped wake — with dependencies the closing time is not on this item,
